INSERT INTO `email_templates` (`id`, `act`, `name`, `subj`, `email_body`, `shortcodes`, `status`, `created_at`, `updated_at`, `lms_id`, `browser_message`, `is_system`, `ecommerce`) VALUES
(1, 'OffLine_Payment', 'OffLine Payment', 'Offline Payment Request Approved', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nOffline Payment\r\n\r\n</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">{{amount}} {{currency}} added to your balance by offline payment method at {{time}}</p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"amount\":\"Request Amount\",\"time\":\"Balance Added Time\",\"footer\":\"Email footer\"}', 1, '2022-12-23 23:01:23', '2024-01-18 17:01:30', 1, '', 0, 1),
(2, 'Bank_Payment', 'Bank Payment', 'Bank Payment Request Approved', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nBank Payment\r\n\r\n</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">Your request to withdraw ${{amount}} has been approved at {{time}}.</p><p style=\"color: rgb(85, 85, 85);\">Details are as follows:</p><p style=\"color: rgb(85, 85, 85);\"><br></p></div></div><table class=\"table table-bordered\"><tbody><tr><td>Transaction ID</td><td>{{transaction}}</td></tr><tr><td>Bank Name</td><td>{{bank_name}}</td></tr><tr><td>Branch Code</td><td>{{br_code}}</td></tr><tr><td>Account Title</td><td>{{account_title}}</td></tr><tr><td>Account #</td><td>{{account_no}}</td></tr></tbody></table><div class=\"\"><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\"><p style=\"color: rgb(85, 85, 85);\"><br></p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"amount\":\"Request Amount\",\"time\":\"Balance Added Time\", \"transaction\":\"Transaction ID\",\"bank_name\":\"Bank Name\",\"br_code\":\"Branch Code\",\"account_title\":\"Account Title\",\"account_no\":\"Account No\"}', 1, '2022-12-23 23:01:23', '2024-10-03 06:49:16', 1, '', 0, 1),
(3, 'Course_Enroll_Payment', 'Course Enroll Payment ', 'Course Enroll Successfully', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nCourse Enroll Successfully\r\n\r\n</h1></div>\r\n<div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\">You have been successfully enrolled to course {{title}}.</p><table class=\"table table-bordered\"><tbody><tr><td>Course Name</td><td>{{title}}</td></tr><tr><td>Course Price</td><td>{{currency}} {{price}}</td></tr><tr><td>Paid Via</td><td>AuthorizeNet</td></tr><tr><td>Instructor</td><td>{{instructor}}</td></tr><tr><td>Course Type</td><td>{{type}}</td></tr><tr><td>Enroll Time</td><td>{{time}}</td></tr></tbody></table></div></div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"time\":\"Enroll  Time\",\"title\":\"Course Title or Program Title\",\"price\":\"Course Purchase Price\",\"instructor\":\"Course Instructor Name\",\"gateway\":\"Payment Method\",\"type\":\"program, course, timetable, big quiz, full course, prep-course (on-d