(29, 'ResetOTP', 'Send Reset OTP Notification', 'Send Reset OTP Notification', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nSend Reset OTP Notification\r\n\r\n</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">Hello {{name}}, Your otp Code is {{otp}} <br></p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"otp\":\"OTP Code\",\"email\":\"Email Address\",\"name\":\"Name\"}', 1, '2022-12-23 23:02:21', '2024-01-18 16:56:04', 1, '', 0, 0),
(30, 'Course_Assigned_Instructor', 'Course Assigned Instructor', 'New Course Assigned Instructor', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nCourse Assigned Instructor</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">&nbsp;New course <b>{{course}}</b> has been added and assigned to you.&nbsp; Publish successfully at {{time}}.</p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"time\":\"Publish Time\",\"course\":\"Course\"}', 1, '2022-12-23 23:01:23', '2024-05-25 10:21:05', 1, '', 0, 0),
(31, 'Class_Assigned_Instructor', 'Class Assigned Instructor', 'New Class Assigned Instructor', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nClass Assigned Instructor</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">&nbsp;new class added&nbsp;Assigned to you {{class}} publish successfully at {{time}}.</p></div>\r\n</div>\r\n{{footer}}', '{\"time\":\"Publish Time\",\"class\":\"Class Name\"}', 1, '2022-12-23 23:01:23', '2024-05-25 10:13:56', 1, '', 0, 0);
