(32, 'program_coming_installment', 'Program Coming Installment', 'Program Coming Installment', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Program Coming installment</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"\"><br></p>\r\n<p style=\"\">{{amount}}&nbsp; &nbsp;&nbsp;&nbsp;{{date}} {{program}}&nbsp;&nbsp;&nbsp; &nbsp;{{plan}}</p><p style=\"font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; color: rgb(85, 85, 85);\"><br></p><p style=\"font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; color: rgb(85, 85, 85);\"><br></p></div></div>\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"program\":\"Program title\",\"plan\":\"Program Plan\",\"amount\":\"Plan Amount\",\"date\":\"Start Date\"}', 1, '2022-12-23 23:01:23', '2024-05-25 10:18:47', 1, '', 0, 1),
(33, 'program_previous_installment', 'Program Previous Installment', 'Program Previous Installment', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Program Previous installment</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\">{{amount}}&nbsp; &nbsp;&nbsp;&nbsp;{{date}}&nbsp;{{program}}&nbsp;&nbsp;&nbsp; &nbsp;{{plan}}</p><p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p><p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n</div></div>\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"program\":\"Program title\",\"plan\":\"Program Plan\",\"amount\":\"Plan Amount\",\"date\":\"Start Date\"}', 1, '2022-12-23 23:01:23', '2024-01-18 17:12:45', 1, '', 0, 1),
(35, 'New_Student_Login', 'New Login Notification', 'New Login Notification', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nNew login Notification\r\n\r\n</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"\"><font color=\"#555555\" face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\">Hi {{name}},</font></p><p style=\"\"><font color=\"#555555\" face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\">Your account had been logged in successfully  at  {{time}}.</font></p>\r\n</div>\r\n{{footer}}</div>', '{\"name\":\"Student Name\",\"time\":\"Registration Time\", \"type\":\"Student, Instructor, Tutor\"}', 1, '2022-12-23 23:01:51', '2024-07-13 06:05:38', 1, '<p><br><br></p>', 0, 0),
(36, 'Student_Submit_Agreement_Form ', 'Student Agreement Form Submitted', 'Student Agreement Form Submitted', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nStudent Assignment Submitted\r\n\r\n</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\"><a href=\"http://{{url}}\" target=\"_blank\">{{student}}</a><font color=\"#555555\" face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\">&nbsp;Submitted Agreement Form at  {{time}}.</font></p></div>\r\n</div>{{footer}}', '{\"time\":\"Submit Time\",\"student\":\"Student Name\",\"url\":\"Student View\"}', 1, '2022-12-23 23:01:50', '2024-06-10 17:45:00', 1, '', 0, 0),
(37, 'Admin_Approve_Disapprove_Agreement_Form ', 'Admin Approve Disapprove Agreement Form', 'Admin Approve Disapprove Agreement Form', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nStudent Assignment Submitted\r\n\r\n</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\"><font color=\"#555555\" face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\">Admin&nbsp;</font>{{status}} your&nbsp;<span style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\">Agreement Form at  {{time}}. </span></p><p style=\"\"><span style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></span></p><p style=\"\"><span style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"></span></p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"time\":\"Submit Time\",\"status\":\"Approve, Disapprove\"}', 1, '2022-12-23 23:01:50', '2024-01-18 16:37:57', 1, '', 0, 0),
(38, 'Admin_Tutor_Set_Hours ', 'Admin Tutor Set Hours', 'Admin Tutor Set Hours', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nAdmin Tutor Set Hours\r\n\r\n</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"\">Hello! Your tutor hours have been set for {{hours}} hours and at price {{hour_price}}/hr for type {{type}} at {{time}}.</p></div>\r\n</div>\r\n{{footer}}', '{\"time\":\"Submit Time\",\"hours\":\"No. of Hours\",\"type\":\"Nursing or Gen-ed\",\"hour_price\":\"Price\"}', 1, '2022-12-23 23:01:50', '2024-09-03 13:19:44', 1, '', 0, 0),
(39, 'Tutor_Package_Buy', 'Tutor Package Buy', 'Tutor Package Buy', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nTutor Package Buy\r\n\r\n</h1></div>\r\n<p>You have bought new tutor package: {{title}}. </p><p>Price: {{price}}</p><p style=\"\">Allowed Courses: {{allowed_courses}}&nbsp;</p><p style=\"\">Package Options:</p><ul><li>{{option_1}}</li><li>{{option_2}}</li><li>{{option_3}}</li><li>{{option_4}}</li><li>{{option_5}}</li></ul><p style=\"\"><br>{{time}}.\r\n</p></div>\r\n{{footer}}', '{\"time\":\"Submit Time\", \"title\":\"Package Title\", \"price\":\"Package Price\", \"allowed_courses\":\"Allowed Courses\", \"option_1\":\"Option 1\", \"option_2\":\"Option 2\", \"option_3\":\"Option 3\", \"option_4\":\"Option 4\", \"option_5\":\"Option 5\"}', 1, '2022-12-23 23:01:50', '2024-05-25 08:54:41', 1, '', 0, 0),
(40, 'Tutor_Package_Upgrade', 'Tutor Package Upgrade', 'Tutor Package Upgrade', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nTutor Package Upgraded</h1></div><ul><li style=\"padding: 20px;\">\r\n<p style=\"\">Your package has been upgraded to {{title}}.</p><p style=\"\">Your previous package was {{previous_package}}</p><p>Price: {{price}}</p><p>Allowed Courses: {{allowed_courses}}&nbsp;&nbsp;</p><p>Package Options:</p><ul><li>{{option_1}}</li><li>{{option_2}}</li><li>{{option_3}}</li><li>{{option_4}}</li><li>{{option_5}}</li></ul><p><br>{{time}}. </p></li></ul>\r\n</div>\r\n{{footer}}', '{\"time\":\"Submit Time\", \"title\":\"Package Title\", \"price\":\"Package Price\", \"allowed_courses\":\"Allowed Courses\", \"option_1\":\"Option 1\", \"option_2\":\"Option 2\", \"option_3\":\"Option 3\", \"option_4\":\"Option 4\", \"option_5\":\"Option 5\", \"previous_package\":\"Previous Package\"}', 1, '2022-12-23 23:01:50', '2024-05-25 08:49:57', 1, '', 0, 0),
(41, 'Tutor_Review', 'New Review on Tutor', 'New Review on Tutor', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nNew Review on course\r\n\r\n</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">You have received a new review from {{username}} for your tutor profile at {{time}}.</p><p style=\"color: rgb(85, 85, 85);\">Star Ranking: {{star}}<br></p><p style=\"color: rgb(85, 85, 85);\">Review Message: {{review}}. </p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n\r\n\r\n    <div class=\"social_links\">\r\n        <a href=\"https://twitter.com/codetheme\"> <i class=\"fab fa-facebook-f\"></i> </a>\r\n        <a href=\"https://codecanyon.net/user/codethemes/portfolio\"><i class=\"fas fa-code\"></i> </a>\r\n        <a href=\"https://twitter.com/codetheme\" target=\"_blank\"> <i class=\"fab fa-twitter\"></i> </a>\r\n        <a href=\"https://dribbble.com/codethemes\"> <i class=\"fab fa-dribbble\"></i></a>\r\n    </div>\r\n</div>', '{\"time\":\"Submit Time\",\"username\":\"Reviewer name\",\"review\":\"Review\",\"star\":\"Review Star\"}', 1, '2022-12-23 23:01:23', '2024-01-16 21:12:42', 1, '', 0, 0),
