(43, 'Tutor_Slot_Buy', 'Tutor Slot Buy', 'Tutor Slot Bought', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nSlot(s) Bought</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\"><font color=\"#555555\" face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\">A Tutor Slot has been bought with below details:</font><br></p><p style=\"\"><br></p><table class=\"table table-bordered\"><tbody><tr><td>Student Name<br></td><td>{{buyer}}</td></tr><tr><td>Slot(s) Price<br></td><td>{{price}}</td></tr><tr><td>Instructor Name<br></td><td>{{instructor}}</td></tr><tr><td>Buying Time<br></td><td>{{time}}</td></tr><tr><td>Slot(s)<br></td><td>{{slot}}</td></tr></tbody></table></div></div><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\"><br></p></div></div>\r\n{{footer}}', '{\"slot\":\"slot\",\"price\":\"slot price\",\"instructor\":\"Instructor Name\",\"buyer\":\"student name\", \"time\":\"Buying Time\"}', 1, '2022-12-23 23:01:23', '2024-10-19 06:53:01', 1, '', 0, 1),
(44, 'Program_Plans', 'Program Plans', 'Program Plans', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Program Enrolled</h1></div><div style=\"padding: 20px;width:100%\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\"><font face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\" color=\"#555555\">You have successfuly enrolled into following Program:</font><br></p><p style=\"\"><br></p><table class=\"table table-bordered\"><tbody><tr><td>Program Name<br></td><td>{{program}}<br></td></tr><tr><td>Time<br></td><td>{{time}}<br></td></tr></tbody></table></div></div><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\">Your Program Plan Details are as follow:</p><p style=\"\">{{installment}}</p></div></div><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\"><br></p></div>\r\n</div>\r\n{{footer}}', '{\"program\":\"Program Title\", \"installment\":\"installments\",\"buyer\":\"student name\", \"time\":\"Buying Time\"}', 1, '2022-12-23 23:01:23', '2024-10-17 04:52:14', 1, '', 0, 1),
(45, 'Student_Installment_Pay', 'Student Installment Paid', 'Student Installment Paid', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Program Installment<br></h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\"><font face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\" color=\"#555555\">Your Program Plan Installment</font><br></p><p style=\"\"><br></p></div></div><table class=\"table table-bordered\"><tbody><tr><td>Type<br></td><td>{{type}}<br></td></tr><tr><td>Amount<br></td><td>{{price}}<br></td></tr><tr><td>Payer<br></td><td>{{payer}}<br></td></tr><tr><td>Time<br></td><td>{{time}}<br></td></tr><tr><td>Installment<br></td><td>{{detail}}<br></td></tr></tbody></table>\r\n\r\n{{footer}}', '{\"installment\":\"Installment\", \"detail\":\"detail\", \"price\":\"price\", \"payer\":\"Student Name\", \"type\":\"installment\", \"time\":\"Payment Time\"}', 1, '2022-12-23 23:01:23', '2024-05-25 08:40:11', 1, '', 0, 1),
(46, 'Newsletter_Subscribe', 'Newsletter Subscription', 'Newsletter Subscription Successful', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Newsletter Subscribed<br></h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\"><font face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\" color=\"#555555\">Your Newsletter Subscription is Successful.</font><br></p><p style=\"\"><br></p></div></div><table class=\"table table-bordered\"><tbody><tr><td>Subscribe Email<br></td><td>{{subscriber}}<br></td></tr><tr><td>Time<br></td><td>{{time}}<br></td></tr></tbody></table><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\"><br></p></div></div><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\"><br></p></div>\r\n</div>\r\n{{footer}}', '{\"newsletter\":\"newsletter\", \"subscriber\":\"email\", \"time\":\"Subscription Time\"}', 1, '2022-12-23 23:01:23', '2024-05-25 08:34:16', 1, '', 0, 1),
