(48, 'Class_Reminder', 'Class Reminder', 'Class Reminder', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Class Reminder</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\"><font face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\" color=\"#555555\">You have a scheduled class for today. </font></p><p style=\"\"><font face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\" color=\"#555555\">Please find the details below:</font><br></p><p style=\"\"><br></p></div></div><table class=\"table table-bordered\"><tbody><tr><td>Class Name</td><td>{{course}}<br></td></tr><tr><td>Class Date<br></td><td>{{date}}<br></td></tr><tr><td>Due Date<br></td><td>{{date}}<br></td></tr><tr><td>Start Time</td><td>{{stime}}</td></tr><tr><td>End Time</td><td>{{etime}}</td></tr><tr><td>Class Link</td><td>{{link}}</td></tr></tbody></table><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\"><br></p></div></div><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\"></p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"course\":\"Course Name\", \"date\":\"Class Date\", \"stime\":\"Start Time\", \"etime\":\"End Time\",\"link\":\"Class Link\"}', 1, '2024-01-09 21:01:23', '2024-09-03 13:17:30', 1, '', 0, 1),
(49, 'Private_Message', 'Private Message', 'Private Message', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">New Message\r\n\r\n</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\">You have received a new message from <b>{{sender}} at {{at}}.</b></p><p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><b><br></b></p><p style=\"\">{{message}}</p></div>\r\n</div>\r\n{{footer}}', '{\"sender\":\"Sender Name\",\"message\":\"Message Text\",\"at\":\"Time of message\"}', 1, '2024-01-10 15:30:48', '2024-05-25 08:32:32', 1, '', 0, 0),
(50, 'certificate_order', 'Certificate Order', 'Certificate Order', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Certificate Order</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\">The student {{student_name}} has ordered a certificate for {{course}}<b>.</b></p></div>\r\n</div>\r\n{{footer}}', '{\"student_name\":\"Student Name\",\"course\":\"Course Title\"}', 1, '2024-01-17 15:30:48', '2024-05-25 08:16:20', 1, '', 0, 0),
(51, 'Pre_Register_Student', 'Pre Registration Notification', 'Pre Registration', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nPre Registration</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\"><font color=\"#555555\" face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\"><span style=\"font-family: Poppins;\">Hi </span><b><span style=\"font-family: Poppins;\">{{name}},</span></b></font></p><p style=\"\"><font color=\"#555555\" face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\"><span style=\"font-family: Poppins;\">You have successfully complete preregistration as {{type}} at  {{time}}.</span></font></p><p style=\"\"><span style=\"color: rgb(55, 55, 55); font-family: Poppins; font-size: 20px;\">At Merkaii Xcellence, we believe education is the key to unlocking potential, and that\'s why we offer a variety of prep courses designed to fit diverse students and learning styles. We offer accessible learning pathways to fuel your passion for healthcare, regardless of background, experience, or location. Merkaii Xcellence fosters a vibrant and supportive global community where everyone </span><span class=\"font-weight-bold\" style=\"color: rgb(55, 55, 55); font-family: Poppins; font-size: 20px;\">&nbsp;can learn, grow, and achieve their healthcare goals and success.</span></p><p style=\"\"><img src=\"https://merkaiixcelprep.com/public/uploads/editor-image/Untitled-4 (2).png1724766466.png\" style=\"\"><span class=\"font-weight-bold\" style=\"color: rgb(55, 55, 55); font-family: Helvetica; font-size: 20px;\"><br></span></p><p style=\"\"><span class=\"font-weight-bold\" style=\"color: rgb(55, 55, 55); font-family: Helvetica; font-size: 20px;\"><br></span><font color=\"#555555\" face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\"><br></font></p><p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"></p></div>\r\n</div>\r\n{{footer}}', '{\"name\":\"Student Name\",\"time\":\"Registration Time\", \"type\":\"Student, Instructor, Tutor\"}', 1, '2024-04-17 22:01:51', '2024-09-03 13:15:40', 1, '<p><font color=\"#555555\" face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\">A new&nbsp;</font><span style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\">{{typ</span><span style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\">e}}</span><font color=\"#555555\" face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\">&nbsp;{{name}} has registration successfully at {{time}}.</font><br></p>', 0, 0),
(52, 'Meeting_Updated', 'Class Rescheduled', 'Class Rescheduled', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nClass Rescheduled</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">&nbsp;Class for {{course}} has been rescheduled to be held as follows:</p><p style=\"color: rgb(85, 85, 85);\"><br></p></div></div><table class=\"table table-bordered\"><tbody><tr><td>New Date / Time</td><td>{{newdate}} / {{newtime}}<br></td></tr></tbody></table><div class=\"\"><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\"><p style=\"color: rgb(85, 85, 85);\"><br></p></div>\r\n</div>\r\n{{footer}}', '{\"time\":\"Class Time\",\"date\":\"Class Date\",\"newtime\":\"New Time\",\"newdate\":\"New Date\",\"class\":\"Class Name\",\"course\":\"Course Name\"}', 1, '2024-06-11 12:46:45', '2024-10-08 09:51:53', 1, '', 0, 0),
(53, 'Coupon_Issued', 'Coupon Issued', 'Coupon Issued', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Coupon Issued</h1></div><div style=\"font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p><p style=\"color: rgb(85, 85, 85);\">Congratulations <b>{{user}}</b>,</p>\r\n<p style=\"color: rgb(85, 85, 85);\">You have been issued following discount coupon at {{time}}.</p><p style=\"text-align: center; color: rgb(85, 85, 85);font-size:1.2em\"><b>Coupon Code</b></p><p style=\"color: rgb(85, 85, 85);\"><br></p><p style=\"text-align: center; font-size: 1.5em;\"><font color=\"#0000ff\" style=\"background-color: rgb(255, 231, 206);\">{{code}}</font></p><p style=\"color: rgb(85, 85, 85);\"><br></p><p style=\"color: rgb(85, 85, 85);\">This coupon is valid up to <b>{{end_time}}</b></p><p style=\"color: rgb(85, 85, 85);\"><br></p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"time\":\"Issuance Time\",\"user\":\"Issued to\",\"code\":\"Coupon Code\",\"end_time\":\"Coupon Validity\"}', 1, '2022-12-23 23:01:23', '2024-09-25 07:34:18', 1, '', 0, 0),
(54, 'certificate_generated', 'Certificate Generated', 'Certificate Generated', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Certificate Order</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\">The certificate for student <b>{{student_name}}</b> for the {{type}} titled: <b>{{course}}</b> has been generated.</p></div>\r\n</div>\r\n{{footer}}', '{\"student_name\":\"Student Name\",\"course\":\"Program/Course Title\",\"type\":\"Program/Course\"}', 1, '2024-01-17 15:30:48', '2024-07-05 06:44:49', 1, '', 0, 0),
(55, 'Google_Pre_Registration', 'Pre Registered using Gmail', 'Pre Registered using Gmail', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nPre Registered using Gmail\r\n\r\n</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">Hi <b>{{name}}</b>,</p><p style=\"color: rgb(85, 85, 85);\">Your Email Address <b>{{email}}</b> has been registered to our website using Gmail Login at {{time}}. Given below are your login credentials, plz login by using this link:&nbsp;https://mchnursing.com/lms/login</p><p style=\"color: rgb(85, 85, 85);\"><br></p><table class=\"table table-bordered\" style=\"font-family: Poppins, sans-serif;\"><tbody><tr><td>Login Email</td><td>{{email}}</td></tr><tr><td>Password</td><td>{{password}}</td></tr></tbody></table></div></div><div class=\"\"><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\"><p style=\"color: rgb(85, 85, 85);\">Please note that the information given above is confidential and not to be shared with anyone.</p><p style=\"color: rgb(85, 85, 85);\"><br></p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"name\":\"Name\",\"email\":\"Registered Email\",\"password\":\"Generated Password\",\"time\":\"Current Time\"}', 1, '2024-07-13 05:11:02', '2024-07-15 11:40:04', 1, '', 0, 1),
(56, 'Tutor_Package_Expired', 'Tutor Package Expired', 'Tutor Package Expired', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nTutor Package Expired</h1></div>\r\n<p><br></p><p>Thank You for Subscribing. <br>We just wanted to inform you that your Tutor Package has expired and all your current courses have been disabled. In order to continue selling your courses please renew or upgrade your package.</p><p><br></p><p><b>Previous Package expiry Date: {{date}}</b></p><p><br></p></div>\r\n{{footer}}', '{\"date\":\"Expiry Date\", \"title\":\"Package Title\"}', 1, '2024-08-03 06:13:35', '2024-09-03 13:09:07', 1, '', 0, 0),
(57, 'Coupon_Update', 'Coupon Update', 'Coupon Updated', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Coupon Updated</h1></div><div style=\"font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p><p style=\"color: rgb(85, 85, 85);\">Dear&nbsp;<b>{{user}}</b>,</p>\r\n<p style=\"color: rgb(85, 85, 85);\">Your discount coupon has been updated with the following changes at {{time}}.</p><p style=\"text-align: center; color: rgb(85, 85, 85);font-size:1.2em\"><b>Coupon Code</b></p><p style=\"color: rgb(85, 85, 85);\"><br></p><p style=\"text-align: center; font-size: 1.5em;\"><font color=\"#0000ff\" style=\"background-color: rgb(255, 231, 206);\">{{code}}</font></p><p style=\"text-align: center; font-size: 1.5em;\"><font color=\"#0000ff\" style=\"background-color: rgb(255, 231, 206);\"><br></font></p><p style=\"color: rgb(85, 85, 85);\">This coupon is valid up to <b>{{end_time}}</b></p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"time\":\"Issuance Time\",\"user\":\"Issued to\",\"code\":\"Coupon Code\",\"end_time\":\"Coupon Validity\"}', 1, '2022-12-23 23:01:23', '2024-09-25 07:34:50', 1, '', 0, 0),
(58, 'Slot_Cancel', 'Slot Cancel', 'Slot Cancelled', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Tutor Slot Cancelled</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\">Your slot for {{date}} at {{time}} with instructor {{instructor}} has been cancelled.&nbsp;</p><p style=\"\"><span style=\"font-size: 16px;\">Your payment has been refunded to you in you wallet.</span></p><p style=\"\"><br></p><p style=\"\">Refunded Amount: ${{balance}}&nbsp;</p></div></div><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\"><br></p></div></div><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\"><br></p></div>\r\n</div>\r\n{{footer}}', '{\"date\":\"Slot Date\", \"time\":\"Slot Time\",\"instructor\":\"Instructor\", \"balance\":\"Return Balance\"}', 1, '2024-09-28 10:00:51', '2024-09-30 05:58:30', 1, '', 0, 1),
(59, 'Bank_Payment_Declined', 'Bank Payment Declined', 'Bank Payment Request Declined', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nBank Payment\r\n\r\n</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">Your request to withdraw ${{amount}} has been declined at {{time}} for the following reason:</p><p style=\"color: rgb(85, 85, 85);\"><br></p><p style=\"text-align: center; color: rgb(85, 85, 85);\"><span style=\"background-color: rgb(239, 239, 239);\">{{comment}}</span></p><p style=\"color: rgb(85, 85, 85);\"><br></p></div></div><div class=\"\"><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\"><p style=\"color: rgb(85, 85, 85);\"><br></p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"amount\":\"Request Amount\",\"time\":\"Balance Added Time\",\"comment\":\"Reason for Decline\"}', 1, '2024-10-03 23:01:23', '2024-10-03 07:09:26', 1, '', 0, 1),
(60, 'Meeting_Updated_Individual', 'Class Rescheduled', 'Class Rescheduled', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nClass Rescheduled</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">&nbsp;Class for {{course}} has been rescheduled to be held as follows:</p><p style=\"color: rgb(85, 85, 85);\"><br></p></div></div><table class=\"table table-bordered\"><tbody><tr><td>Old Date / Time</td><td>{{date}} / {{time}}</td></tr><tr><td>New Date / Time</td><td>{{newdate}} / {{newtime}}<br></td></tr></tbody></table><div class=\"\"><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\"><p style=\"color: rgb(85, 85, 85);\"><br></p></div>\r\n</div>\r\n{{footer}}', '{\"time\":\"Class Time\",\"date\":\"Class Date\",\"newtime\":\"New Time\",\"newdate\":\"New Date\",\"class\":\"Class Name\",\"course\":\"Course Name\"}', 1, '2024-06-11 12:46:45', '2024-10-09 02:12:48', 1, '', 0, 0),
(61, 'Class_Cancelled', 'Class Cancelled', 'Class Cancellation', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Class Cancellation</h1></div><div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\"><br></p>\r\n<p style=\"\"><font face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\" color=\"#555555\">One of your classes have been {{request}}.</font></p><p style=\"\"><font face=\"Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif\" color=\"#555555\">Please find the details below:</font><br></p><p style=\"\"><br></p><table class=\"table table-bordered\"><tbody><tr><td>Class Name</td><td>{{course}}<br></td></tr><tr><td>Class Date<br></td><td>{{date}}<br></td></tr><tr><td>Start Time</td><td>{{stime}}</td></tr><tr><td>End Time</td><td>{{etime}}</td></tr></tbody></table><p>{{comment}}</p></div></div><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\"><br></p></div></div><div class=\"\"><div style=\"padding: 20px;\"><p style=\"\"></p></div>\r\n</div>\r\n\r\n<div class=\"email_invite_wrapper\" style=\"text-align: center\">\r\n{{footer}}\r\n</div>', '{\"course\":\"Course Name\", \"date\":\"Class Date\", \"stime\":\"Start Time\", \"etime\":\"End Time\"}', 1, '2024-10-16 21:01:23', '2024-10-17 05:08:50', 1, '', 0, 1);
INSERT INTO `email_templates` (`id`, `act`, `name`, `subj`, `email_body`, `shortcodes`, `status`, `created_at`, `updated_at`, `lms_id`, `browser_message`, `is_system`, `ecommerce`) VALUES
(62, 'Class_Created', 'New Class Created', 'New Class Created', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nNew Class Created</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">&nbsp;A New Class has been added with following details:</p><p style=\"color: rgb(85, 85, 85);\"><br></p><p style=\"color: rgb(85, 85, 85);\"><br></p></div></div><table class=\"table table-bordered\"><tbody><tr><td>Course Name</td><td>{{course}}</td></tr><tr><td>Course Type</td><td>{{type}}</td></tr><tr><td>Class Name</td><td>{{class}}</td></tr><tr><td>Start Date</td><td>{{start_date}}</td></tr><tr><td>End Date</td><td>{{end_date}}</td></tr><tr><td>Class Day</td><td>{{day}}</td></tr></tbody></table><div class=\"\"><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\"><p style=\"color: rgb(85, 85, 85);\"><br></p></div>\r\n</div>\r\n{{footer}}', '{\"course\":\"Course Name\",\"type\":\"Course Type\",\"class\":\"Class Name\",\"start_date\":\"Start Date\",\"end_date\":\"End Date\",\"stime\":\"Start Time\",\"etime\":\"End Time\",\"day\":\"Class Day\"}', 1, '2024-11-12 23:01:23', '2024-11-13 23:36:48', 1, '', 0, 0),
(63, 'accept_programplan_change_request', 'Program Payment Plan Changed', 'Program Payment Plan Changed', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nProgram Payment Plan Changed</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">Request for change of Payment Plan for Installment of <b>{{program}}</b> has been accepted.</p><p style=\"color: rgb(85, 85, 85);\">Following are thenew&nbsp; detail for payment plan.</p><p style=\"color: rgb(85, 85, 85);\"><br></p><p style=\"color: rgb(85, 85, 85);\"><span style=\"font-weight: bolder;\">Plan Detail:</span>&nbsp;{{plan}}</p></div></div><table class=\"table table-bordered\"><tbody><tr><td><b>Type</b></td><td><b>Start Date</b></td><td><b>End Date</b></td><td><b>Amount</b></td></tr><tr><td>{{type}}</td><td>{{sdate}}</td><td>{{edate}}</td><td>{{amount}}</td></tr></tbody></table><div class=\"\"><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\"><p style=\"color: rgb(85, 85, 85);\"><br></p></div>\r\n</div>\r\n{{footer}}', '{\"program\":\"Program Name\",\"type\":\"Installment Type\",\"sdate\":\"Start Date\",\"edate\":\"End Date\",\"amount\":\"Amount\"}', 1, '2024-11-12 23:01:23', '2025-03-28 02:35:27', 1, '', 0, 0),
(64, 'reject_programplan_change_request', 'Program Payment Plan Change Rejected', 'Program Payment Plan Change Rejected', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nProgram Payment Plan Change Rejected</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">Request for change of Payment Plan for Installment of <b>{{program}}</b> has been rejected.</p><p style=\"color: rgb(85, 85, 85);\">Following are the detail for payment plan.</p><p style=\"color: rgb(85, 85, 85);\"><br></p><p style=\"color: rgb(85, 85, 85);\"><span style=\"font-weight: bolder;\">Plan Detail:</span>&nbsp;{{plan}}</p></div></div><table class=\"table table-bordered\"><tbody><tr><td><b>Type</b></td><td><b>Start Date</b></td><td><b>End Date</b></td><td><b>Amount</b></td></tr><tr><td>{{type}}</td><td>{{sdate}}</td><td>{{edate}}</td><td>{{amount}}</td></tr></tbody></table><div class=\"\"><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\"><p style=\"color: rgb(85, 85, 85);\"><br></p></div>\r\n</div>\r\n{{footer}}', '{\"program\":\"Program Name\",\"type\":\"Installment Type\",\"sdate\":\"Start Date\",\"edate\":\"End Date\",\"amount\":\"Amount\"}', 1, '2024-11-12 23:01:23', '2025-03-28 02:35:03', 1, '', 0, 0),
(65, 'program_plan_installment_change_requested', 'Program Payment Plan Change Requested', 'Program Payment Plan Change Requested', '<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\r\nProgram Payment Plan Change Requested</h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85);\"><br></p>\r\n<p style=\"color: rgb(85, 85, 85);\">Request for change of Payment Plan for Installment of <b>{{program}}</b> has been requested by <b>{{student}}</b>.</p><p style=\"color: rgb(85, 85, 85);\"><br></p><p style=\"color: rgb(85, 85, 85);\"><b>Plan Detail:</b> {{plan}}</p></div><table class=\"table table-bordered\"><tbody><tr><td><b>Type</b></td><td><b>Start Date</b></td><td><b>End Date</b></td><td><b>Amount</b></td></tr><tr><td>{{type}}</td><td>{{sdate}}</td><td>{{edate}}</td><td>{{amount}}</td></tr></tbody></table></div>\r\n{{footer}}', '{\"program\":\"Program Name\",\"student\":\"Student Name\"}', 1, '2024-11-12 23:01:23', '2025-03-28 02:34:20', 1, '', 0, 0),
(66, 'Shop_Order', 'Shop Order', 'Shop Order', '<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\r\n<style>\r\n\r\n     .social_links {\r\n        background: #F4F4F8;\r\n        padding: 15px;\r\n        margin: 30px 0 30px 0;\r\n    }\r\n\r\n    .social_links a {\r\n        display: inline-block;\r\n        font-size: 15px;\r\n        color: #252B33;\r\n        padding: 5px;\r\n    }\r\n\r\n\r\n</style>\r\n\r\n<div class=\"\">\r\n<div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">Shop Order</h1></div>\r\n<div style=\"padding: 20px;\">\r\n<p style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;\">Your order status has been updated. Please log in to your account to view the latest details.</p><table class=\"table table-bordered\"><tbody><tr><td>Order Number</td><td>{{order_no}}</td></tr><tr><td>Product Title</td><td>{{title}}</td></tr><tr><td>Paid Via</td><td>AuthorizeNet</td></tr><tr><td>Purchase Amount</td><td>{{currency}} {{amount}}</td></tr><tr><td>Payment Status</td><td>{{payment_status}}</td></tr><tr><td>Order&nbsp;Status</td><td>{{order_status}}</td></tr></tbody></table><span style=\"color: rgb(85, 85, 85); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">&nbsp;If you have any questions, feel free to contact us.</span></div></div><div class=\"email_invite_wrapper\" style=\"text-align: center\">{{footer}}\r\n</div>', '{\"order_no\":\"Order Number\",\"title\":\"Product/book title\",\"price\":\"Product Purchase Price\",\"Payment_Status\":\"Payment Status\",\"Currency\":\"Payment Currency\",\"Amount\":\"Payment Amount\",\"Order_Status\":\"Order status\"}', 1, '2022-12-23 23:01:23', '2025-11-24 15:16:01', 1, '', 0, 1);
