(3, 'purchase  Your Weakest Subject to Begin', '', 'Purchase the course that caused you discomfort and made it hard for you to sleep after failing.', 3, 'public/uploads/main/images/04-04-2025/67efa76651459.jpeg', 1, '2025-04-04 05:33:26', '2025-11-25 04:39:41', 1),
(4, 'Learn, connect  and Discuss', '', 'Courses are organized into weeks and steps. You can connect with other students and tutors during your learning experience.', 4, 'public/uploads/main/images/25-11-2025/69257195b3851.jpeg', 1, '2025-04-04 05:34:31', '2025-11-25 05:06:29', 1),
(5, 'choose a program', '', 'You can choose any program plan from our search page or Program listing page connected to Florida Remedial Programs', 1, 'public/uploads/main/images/25-11-2025/6925707284f77.png', 1, '2025-04-04 07:26:45', '2025-11-25 05:01:38', 1);
