INSERT INTO `programs` (`id`, `seq_no`, `programtitle`, `subtitle`, `totalcost`, `discount_price`, `duration`, `requirement`, `discription`, `outcome`, `numberofcourses`, `allcourses`, `faqs`, `payment_plan`, `reveune`, `total_enrolled`, `user_id`, `image`, `icon`, `review_id`, `featured`, `status`, `created_at`, `updated_at`, `lms_id`) VALUES
(1, 1, 'FLBON NCLEX-RN REPEAT REMEDIATION', 'Transform Setbacks into Success and Pass Your NCLEX Exam', NULL, 0, NULL, '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>To Achieve Success, and before embarking on this exciting journey You`ll Need These Requirements:</strong>&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) A commitment to active participation.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Strong foundation in fundamental nursing concepts &nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(3) Dedication to completing all course readings and assignments.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(4) Openness to feedback and personalized guidance.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(5) Consistent engagement with practice questions and case studies.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(6) A willingness to change your study habits.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(7) A positive mindset, attitude and unwavering determination.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(8) A laptop, internet, quiet space (without distraction).</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Ready to conquer the NCLEX®? Let`s do this together!</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">So, how do you get started? The enrollment process is straightforward.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">You’ll need to provide proof of your previous NCLEX®&nbsp;attempts and complete the online application form.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Once accepted, you’ll receive a detailed schedule and course materials to help you hit the ground running.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Note:</strong>&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It`s important to note that applicants with criminal offenses beyond minor traffic violations should consult the Florida Board of Nursing’s website</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">to understand how these issues might affect eligibility for RN licensure.</span></p><p>&nbsp;</p>', '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Introduction to the Instructor-Led Remediation Course for Nurses – REPEAT NCLEX TEST-TAKERS</strong></span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Feeling stuck on the NCLEX-RN Exam?&nbsp;</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Merakii’s (MCOH) Florida Board of Nursing-Approved NCLEX® Remediation Prep Program&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Designed to meet the requirements for determined nurses who’ve attempted the NCLEX® multiple times without success</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">And who are ready for winning strategies to retake the NCLEX® exam and succeed.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>This course has been designed in accordance with Florida Rules as set forth in 64B9-3.0025 Remedial Courses for Re-Examination.</strong></span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>There are two main Section:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) Strategies course is designed to ensure the student is prepared with comprehensive critical thinking skills, test taking strategies, and methods of success.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Content Course is designed to ensure the student learn, understand, and evaluate each subject.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Courses Covered In Accordance with NCLEX Test Plan:</strong></span></p><ul><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">NCLEX Test Taking Strategies</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Adult Health-Medical Surgical Nursing w/lab - <strong>Physiological Integrity</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Maternity &amp; Newborn Nursing w/lab - <strong>Health Promotion and Maintenance</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Pediatric Nursing w/lab - <strong>Health Promotion and Maintenance</strong>&nbsp;</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Pharmacology &amp; Medication Calculations - <strong>Physiological Integrity</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Geriatric Nursing w/lab - <strong>Health Promotion &amp; Maintenance, Physiological Integrity, Psychosocial Integrity</strong>&nbsp;</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Psychiatric Mental Health Nursing - <strong>Psychosocial Integrity</strong>&nbsp;</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Legal &amp; Ethical Issues in Nursing - <strong>Safe, Effective Care Environment</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Cultural Diversity in Health Practice - <strong>Psychosocial Integrity</strong></span></li></ul><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">&nbsp; &nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>To enroll in the remediation program, you must:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) Be a Nursing Graduate: Have completed FLBON approved nursing program and be eligible to sit for the NCLEX®.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Unsuccessful NCLEX®: Have attempted the NCLEX®&nbsp;Exam three (3) consecutive or more times without passing.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(3) You will need a letter to begin the remedial course. To request this letter, email&nbsp;</span><a href=\"mailto:MQA.NursingAppStatus@flhealth.gov\"><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>MQA.NursingAppStatus@flhealth.gov</strong></span></a><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>.</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(4) Commit to the Program: Be willing to dedicate the necessary time and effort to complete the coursework and practice sessions.</span></p><p>&nbsp;</p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Required Documents For Enrollment:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">1. Copy of Driver License or Government issued Photo ID – For identification purpose.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">2. Copy of SS# Card - Last 4 of SS# enter this on the Enrollment Agreement&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">3. Enrollment Agreement form (online)&nbsp; &nbsp; &nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">4. BLS or CPR Card for Healthcare Providers – AHA or Red Cross</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">5. Immunization record: MMR (Titer), Varicella, Tetanus, Tdap, Negative TB screen</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">6. Proof of Hepatitis B or Decline Waiver form</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">7. Level 2 background check (if needed): ORI for fingerprinting will be provided.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">8. Proof of Health Insurance for Clinical&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">9. Complete Physical exam (less than 1-year)</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">10. All health reports must be signed by applicant’s healthcare provider (MD, PA, APRN)&nbsp;&nbsp;</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Let`s turn those attempts into triumph! You`re not alone, and we`re here to help!</strong></span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Note:</strong>&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It`s important to note that applicants with criminal offenses beyond minor traffic violations should consult the Florida Board of Nursing’s website</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">to understand how these issues might affect eligibility for RN licensure.</span></p><p>&nbsp;</p>', '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>At the Completion of this Course, here`s &nbsp;– What You`ll Gain:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) Enhance Knowledge-Targeted content review focusing on your weak areas.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Improve Test-Taking Skills-Proven test-taking strategies to boost confidence.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(3) Effective critical thinking skills for NCLEX-style questions.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(4) Personalized study plans tailored to your learning style.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(5) Achieve Success-Confidence to approach the exam without fear.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(6) A clear understanding of the NCLEX® exam format.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(7) Develop Clinical Skills: Hone your practical skills through hands-on practice and simulations.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>All About the NCLEX®</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Okay, let`s discuss the actual figures, nurses.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">In 2024, first-time U.S.-Educated NCLEX-RN test-takers achieved a pass rate of 91.16%.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">That`s great! However, the surprising fact is that for students retaking the exam, the percentage falls to a concerning 50.93%. That hurts.&nbsp;</span><br><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>What is the reason for the large gap?&nbsp;</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It is widely acknowledged that the NCLEX® is challenging for everyone.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Those numbers clearly indicate that your greatest opportunity for success lies in that initial (first-time) attempt.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Retaking it doesn`t mean you`re out of options, but it does indicate that you need to change your approach significantly.&nbsp;</span><br><span style=\"font-family:Jost;\">&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>A strategic plan is necessary for success.</strong></span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Stop trying to memorize everything at the last minute. Don`t limit yourself to reading textbooks only.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>We are discussing:</strong></span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">* <strong>Focused content review:</strong> Identifying your weaknesses and addressing those knowledge gaps.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">* <strong>Developing test-taking strategies:</strong> Understanding how to tackle challenging questions and effectively manage your time.&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">* <strong>Practical experience:</strong> Simulating the actual NCLEX® experience with examination-style questions similar to those on the test.&nbsp;</span><br><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Make sure to take control of the situation.&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">With the right tools and strategies, you can succeed in the NCLEX®.&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Note:</strong>&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It`s important to note that applicants with criminal offenses beyond minor traffic violations should consult the Florida Board of Nursing’s website</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">to understand how these issues might affect eligibility for RN licensure.</span></p><p>&nbsp;</p>', '0', '[\"1\",\"5\"]', '[\"78\",\"76\",\"79\",\"74\"]', '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">- Program Tuition Cost: $2,250.00, which must be paid in full by the registration deadline.</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">- Payment Plan is available: A deposit of $1000 before the beginning of class with the remainder paid in three (3) installments within 60 days.&nbsp;</span></p><ul><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Additional costs details include books, uniforms (purple or blue bottom and white top - varies), Virtual Simulation, HESI Testing, and Proctored Exam.</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Registration Fee is included in cost and is nonrefundable $100.</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Please note that <strong>ALL Sales are Final</strong>. There will be <strong>NO Refunds</strong> provided for any reason.</span></li></ul>', '0', 1, 1, 'public/uploads/main/images/04-09-2025/68b9751078c36.jpeg', 'public/uploads/main/images/04-09-2025/course-1756984592766247076.png', 0, 1, 1, '2025-09-04 08:16:32', '2025-09-12 08:24:19', 1),
(2, 2, 'FLBON INTERNATIONAL EDUCATED REMEDIATION', 'Dreaming of a US Nursing Career , You\'ve got the heart, Now let\'s nail the NCLEX!', NULL, 0, NULL, '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>To Achieve Success, and before embarking on this exciting journey You`ll Need These Requirements:</strong>&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) A commitment to active participation.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Strong foundation in fundamental nursing concepts &nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(3) Dedication to completing all course readings and assignments.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(4) Openness to feedback and personalized guidance.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(5) Consistent engagement with practice questions and case studies.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(6) A willingness to change your study habits.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(7) A positive mindset, attitude and unwavering determination.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(8) A laptop, internet, quiet space (without distraction).</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Ready to conquer the NCLEX®? Let`s do this together!</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">So, how do you get started? The enrollment process is straightforward.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">You’ll need to provide proof of your previous NCLEX®&nbsp;attempts and complete the online application form.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Once accepted, you’ll receive a detailed schedule and course materials to help you hit the ground running.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Note:</strong>&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It`s important to note that applicants with criminal offenses beyond minor traffic violations should consult the Florida Board of Nursing’s website</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">to understand how these issues might affect eligibility for RN licensure.</span></p><p>&nbsp;</p>', '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Introduction to the Instructor-Led Remediation Course for Nurses – REPEAT NCLEX TEST-TAKERS</strong></span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Feeling stuck on the NCLEX-RN Exam?&nbsp;</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Merakii’s (MCOH) Florida Board of Nursing-Approved NCLEX® Remediation Prep Program&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Designed to meet the requirements for determined nurses who’ve attempted the NCLEX® multiple times without success</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">And who are ready for winning strategies to retake the NCLEX® exam and succeed.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>This course has been designed in accordance with Florida Rules as set forth in 64B9-3.0025 Remedial Courses for Re-Examination.</strong></span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>There are two main Section:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) Strategies course is designed to ensure the student is prepared with comprehensive critical thinking skills, test taking strategies, and methods of success.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Content Course is designed to ensure the student learn, understand, and evaluate each subject.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Courses Covered In Accordance with NCLEX Test Plan:</strong></span></p><ul><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">NCLEX Test Taking Strategies</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Adult Health-Medical Surgical Nursing w/lab - <strong>Physiological Integrity</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Maternity &amp; Newborn Nursing w/lab - <strong>Health Promotion and Maintenance</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Pediatric Nursing w/lab - <strong>Health Promotion and Maintenance</strong>&nbsp;</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Pharmacology &amp; Medication Calculations - <strong>Physiological Integrity</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Geriatric Nursing w/lab - <strong>Health Promotion &amp; Maintenance, Physiological Integrity, Psychosocial Integrity</strong>&nbsp;</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Psychiatric Mental Health Nursing - <strong>Psychosocial Integrity</strong>&nbsp;</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Legal &amp; Ethical Issues in Nursing - <strong>Safe, Effective Care Environment</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Cultural Diversity in Health Practice - <strong>Psychosocial Integrity</strong></span></li></ul><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">&nbsp; &nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>To enroll in the remediation program, you must:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) Be a Nursing Graduate: Have completed FLBON approved nursing program and be eligible to sit for the NCLEX®.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Unsuccessful NCLEX®: Have attempted the NCLEX®&nbsp;Exam three (3) consecutive or more times without passing.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(3) You will need a letter to begin the remedial course. To request this letter, email&nbsp;</span><a href=\"mailto:MQA.NursingAppStatus@flhealth.gov\"><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>MQA.NursingAppStatus@flhealth.gov</strong></span></a><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>.</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(4) Commit to the Program: Be willing to dedicate the necessary time and effort to complete the coursework and practice sessions.</span></p><p>&nbsp;</p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Required Documents For Enrollment:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">1. Copy of Driver License or Government issued Photo ID – For identification purpose.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">2. Copy of SS# Card - Last 4 of SS# enter this on the Enrollment Agreement&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">3. Enrollment Agreement form (online)&nbsp; &nbsp; &nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">4. BLS or CPR Card for Healthcare Providers – AHA or Red Cross</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">5. Immunization record: MMR (Titer), Varicella, Tetanus, Tdap, Negative TB screen</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">6. Proof of Hepatitis B or Decline Waiver form</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">7. Level 2 background check (if needed): ORI for fingerprinting will be provided.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">8. Proof of Health Insurance for Clinical&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">9. Complete Physical exam (less than 1-year)</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">10. All health reports must be signed by applicant’s healthcare provider (MD, PA, APRN)&nbsp;&nbsp;</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Let`s turn those attempts into triumph! You`re not alone, and we`re here to help!</strong></span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Note:</strong>&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It`s important to note that applicants with criminal offenses beyond minor traffic violations should consult the Florida Board of Nursing’s website</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">to understand how these issues might affect eligibility for RN licensure.</span></p><p>&nbsp;</p>', '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>At the Completion of this Course, here`s &nbsp;– What You`ll Gain:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) Enhance Knowledge-Targeted content review focusing on your weak areas.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Improve Test-Taking Skills-Proven test-taking strategies to boost confidence.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(3) Effective critical thinking skills for NCLEX-style questions.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(4) Personalized study plans tailored to your learning style.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(5) Achieve Success-Confidence to approach the exam without fear.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(6) A clear understanding of the NCLEX® exam format.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(7) Develop Clinical Skills: Hone your practical skills through hands-on practice and simulations.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>All About the NCLEX®</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Okay, let`s discuss the actual figures, nurses.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">In 2024, first-time U.S.-Educated NCLEX-RN test-takers achieved a pass rate of 91.16%.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">That`s great! However, the surprising fact is that for students retaking the exam, the percentage falls to a concerning 50.93%. That hurts.&nbsp;</span><br><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>What is the reason for the large gap?&nbsp;</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It is widely acknowledged that the NCLEX® is challenging for everyone.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Those numbers clearly indicate that your greatest opportunity for success lies in that initial (first-time) attempt.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Retaking it doesn`t mean you`re out of options, but it does indicate that you need to change your approach significantly.&nbsp;</span><br><span style=\"font-family:Jost;\">&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>A strategic plan is necessary for success.</strong></span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Stop trying to memorize everything at the last minute. Don`t limit yourself to reading textbooks only.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>We are discussing:</strong></span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">* <strong>Focused content review:</strong> Identifying your weaknesses and addressing those knowledge gaps.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">* <strong>Developing test-taking strategies:</strong> Understanding how to tackle challenging questions and effectively manage your time.&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">* <strong>Practical experience:</strong> Simulating the actual NCLEX® experience with examination-style questions similar to those on the test.&nbsp;</span><br><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Make sure to take control of the situation.&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">With the right tools and strategies, you can succeed in the NCLEX®.&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Note:</strong>&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It`s important to note that applicants with criminal offenses beyond minor traffic violations should consult the Florida Board of Nursing’s website</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">to understand how these issues might affect eligibility for RN licensure.</span></p><p>&nbsp;</p>', '0', '[\"1\"]', '[\"78\",\"76\",\"79\",\"74\",\"80\",\"77\",\"75\",\"73\"]', '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">- Program Tuition Cost: $2,250.00, which must be paid in full by the registration deadline.</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">- Payment Plan is available: A deposit of $1000 before the beginning of class with the remainder paid in three (3) installments within 60 days.&nbsp;</span></p><ul><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Additional costs details include books, uniforms (purple or blue bottom and white top - varies), Virtual Simulation, HESI Testing, and Proctored Exam.</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Registration Fee is included in cost and is nonrefundable $100.</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Please note that <strong>ALL Sales are Final</strong>. There will be <strong>NO Refunds</strong> provided for any reason.</span></li></ul>', '0', 7, 1, 'public/uploads/main/images/04-09-2025/68b9762eb7389.jpeg', 'public/uploads/main/images/04-09-2025/course-1756984878524919269.png', 0, 1, 1, '2025-09-04 08:21:18', '2025-09-20 04:43:14', 1),
(3, 3, 'FLBON LICENSEE ENDORSEMENT REMEDIATION', 'Ready to expand and plant roots in another state?', NULL, 0, NULL, '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>To Achieve Success, and before embarking on this exciting journey You`ll Need These Requirements:</strong>&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) A commitment to active participation.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Strong foundation in fundamental nursing concepts &nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(3) Dedication to completing all course readings and assignments.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(4) Openness to feedback and personalized guidance.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(5) Consistent engagement with practice questions and case studies.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(6) A willingness to change your study habits.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(7) A positive mindset, attitude and unwavering determination.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(8) A laptop, internet, quiet space (without distraction).</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Ready to conquer the NCLEX®? Let`s do this together!</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">So, how do you get started? The enrollment process is straightforward.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">You’ll need to provide proof of your previous NCLEX®&nbsp;attempts and complete the online application form.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Once accepted, you’ll receive a detailed schedule and course materials to help you hit the ground running.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Note:</strong>&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It`s important to note that applicants with criminal offenses beyond minor traffic violations should consult the Florida Board of Nursing’s website</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">to understand how these issues might affect eligibility for RN licensure.</span></p><p>&nbsp;</p>', '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Introduction to the Instructor-Led Remediation Course for Nurses – REPEAT NCLEX TEST-TAKERS</strong></span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Feeling stuck on the NCLEX-RN Exam?&nbsp;</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Merakii’s (MCOH) Florida Board of Nursing-Approved NCLEX® Remediation Prep Program&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Designed to meet the requirements for determined nurses who’ve attempted the NCLEX® multiple times without success</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">And who are ready for winning strategies to retake the NCLEX® exam and succeed.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>This course has been designed in accordance with Florida Rules as set forth in 64B9-3.0025 Remedial Courses for Re-Examination.</strong></span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>There are two main Section:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) Strategies course is designed to ensure the student is prepared with comprehensive critical thinking skills, test taking strategies, and methods of success.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Content Course is designed to ensure the student learn, understand, and evaluate each subject.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Courses Covered In Accordance with NCLEX Test Plan:</strong></span></p><ul><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">NCLEX Test Taking Strategies</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Adult Health-Medical Surgical Nursing w/lab - <strong>Physiological Integrity</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Maternity &amp; Newborn Nursing w/lab - <strong>Health Promotion and Maintenance</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Pediatric Nursing w/lab - <strong>Health Promotion and Maintenance</strong>&nbsp;</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Pharmacology &amp; Medication Calculations - <strong>Physiological Integrity</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Geriatric Nursing w/lab - <strong>Health Promotion &amp; Maintenance, Physiological Integrity, Psychosocial Integrity</strong>&nbsp;</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Psychiatric Mental Health Nursing - <strong>Psychosocial Integrity</strong>&nbsp;</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Legal &amp; Ethical Issues in Nursing - <strong>Safe, Effective Care Environment</strong></span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Cultural Diversity in Health Practice - <strong>Psychosocial Integrity</strong></span></li></ul><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">&nbsp; &nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>To enroll in the remediation program, you must:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) Be a Nursing Graduate: Have completed FLBON approved nursing program and be eligible to sit for the NCLEX®.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Unsuccessful NCLEX®: Have attempted the NCLEX®&nbsp;Exam three (3) consecutive or more times without passing.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(3) You will need a letter to begin the remedial course. To request this letter, email&nbsp;</span><a href=\"mailto:MQA.NursingAppStatus@flhealth.gov\"><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>MQA.NursingAppStatus@flhealth.gov</strong></span></a><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>.</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(4) Commit to the Program: Be willing to dedicate the necessary time and effort to complete the coursework and practice sessions.</span></p><p>&nbsp;</p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Required Documents For Enrollment:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">1. Copy of Driver License or Government issued Photo ID – For identification purpose.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">2. Copy of SS# Card - Last 4 of SS# enter this on the Enrollment Agreement&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">3. Enrollment Agreement form (online)&nbsp; &nbsp; &nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">4. BLS or CPR Card for Healthcare Providers – AHA or Red Cross</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">5. Immunization record: MMR (Titer), Varicella, Tetanus, Tdap, Negative TB screen</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">6. Proof of Hepatitis B or Decline Waiver form</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">7. Level 2 background check (if needed): ORI for fingerprinting will be provided.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">8. Proof of Health Insurance for Clinical&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">9. Complete Physical exam (less than 1-year)</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">10. All health reports must be signed by applicant’s healthcare provider (MD, PA, APRN)&nbsp;&nbsp;</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Let`s turn those attempts into triumph! You`re not alone, and we`re here to help!</strong></span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Note:</strong>&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It`s important to note that applicants with criminal offenses beyond minor traffic violations should consult the Florida Board of Nursing’s website</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">to understand how these issues might affect eligibility for RN licensure.</span></p><p>&nbsp;</p>', '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>At the Completion of this Course, here`s &nbsp;– What You`ll Gain:</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(1) Enhance Knowledge-Targeted content review focusing on your weak areas.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(2) Improve Test-Taking Skills-Proven test-taking strategies to boost confidence.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(3) Effective critical thinking skills for NCLEX-style questions.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(4) Personalized study plans tailored to your learning style.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(5) Achieve Success-Confidence to approach the exam without fear.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(6) A clear understanding of the NCLEX® exam format.</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">(7) Develop Clinical Skills: Hone your practical skills through hands-on practice and simulations.</span></p><p>&nbsp;</p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>All About the NCLEX®</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Okay, let`s discuss the actual figures, nurses.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">In 2024, first-time U.S.-Educated NCLEX-RN test-takers achieved a pass rate of 91.16%.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">That`s great! However, the surprising fact is that for students retaking the exam, the percentage falls to a concerning 50.93%. That hurts.&nbsp;</span><br><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>What is the reason for the large gap?&nbsp;</strong></span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It is widely acknowledged that the NCLEX® is challenging for everyone.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Those numbers clearly indicate that your greatest opportunity for success lies in that initial (first-time) attempt.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Retaking it doesn`t mean you`re out of options, but it does indicate that you need to change your approach significantly.&nbsp;</span><br><span style=\"font-family:Jost;\">&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>A strategic plan is necessary for success.</strong></span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Stop trying to memorize everything at the last minute. Don`t limit yourself to reading textbooks only.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>We are discussing:</strong></span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">* <strong>Focused content review:</strong> Identifying your weaknesses and addressing those knowledge gaps.&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">* <strong>Developing test-taking strategies:</strong> Understanding how to tackle challenging questions and effectively manage your time.&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">* <strong>Practical experience:</strong> Simulating the actual NCLEX® experience with examination-style questions similar to those on the test.&nbsp;</span><br><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Make sure to take control of the situation.&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">With the right tools and strategies, you can succeed in the NCLEX®.&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">&nbsp;</span></p><p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\"><strong>Note:</strong>&nbsp;</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">It`s important to note that applicants with criminal offenses beyond minor traffic violations should consult the Florida Board of Nursing’s website</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">to understand how these issues might affect eligibility for RN licensure.</span></p><p>&nbsp;</p>', '0', '[\"1\"]', '[\"57\",\"56\",\"55\",\"54\",\"52\",\"53\",\"51\"]', '<p><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">- Program Tuition Cost: $2,250.00, which must be paid in full by the registration deadline.</span><br><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">- Payment Plan is available: A deposit of $1000 before the beginning of class with the remainder paid in three (3) installments within 60 days.&nbsp;</span></p><ul><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Additional costs details include books, uniforms (purple or blue bottom and white top - varies), Virtual Simulation, HESI Testing, and Proctored Exam.</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Registration Fee is included in cost and is nonrefundable $100.</span></li><li><span style=\"color:hsl(0,0%,0%);font-family:Jost;font-size:16px;\">Please note that <strong>ALL Sales are Final</strong>. There will be <strong>NO Refunds</strong> provided for any reason.</span></li></ul>', '0', 2, 1, 'public/uploads/main/images/04-09-2025/68b976fd4f400.jpeg', 'public/uploads/main/images/04-09-2025/course-1756985085926762439.png', 0, 1, 1, '2025-09-04 08:24:45', '2025-10-28 08:40:03', 1);
INSERT INTO `programs` (`id`, `seq_no`, `programtitle`, `subtitle`, `totalcost`, `discount_price`, `duration`, `requirement`, `discription`, `outcome`, `numberofcourses`, `allcourses`, `faqs`, `payment_plan`, `reveune`, `total_enrolled`, `user_id`, `image`, `icon`, `review_id`, `featured`, `status`, `created_at`, `updated_at`, `lms_id`) VALUES
(8, 5, 'BS CS', 'Bechlor', NULL, 0, NULL, '<h4><strong>Academic Prerequisites:</strong></h4><ul><li>Basic understanding of computers and operating systems</li><li>Prior experience with any programming logic (like C, Python, or pseudocode) — optional but helpful</li></ul><h4><strong>Technical Requirements:</strong></h4><ul><li>Laptop or PC (minimum 4GB RAM recommended)</li><li>Installed Java Development Kit (JDK 17 or higher)</li><li>Integrated Development Environment (IDE): IntelliJ IDEA / Eclipse / NetBeans / VS Code</li><li>Internet connection (for library access, dependencies, and tutorials)</li></ul><h4><strong>Textbooks &amp; References:</strong></h4><ol><li><i>Java: The Complete Reference</i> by <strong>Herbert Schildt</strong></li><li><i>Head First Java</i> by <strong>Kathy Sierra &amp; Bert Bates</strong></li><li><i>Effective Java</i> by <strong>Joshua Bloch</strong></li><li>Oracle Java Documentation (https://docs.oracle.com/javase)</li></ol><h3><strong>? Teaching Methodology</strong></h3><ul><li>Lectures and live coding demonstrations</li><li>Practical lab sessions</li><li>Assignments and quizzes</li><li>Midterm and final project (individual or group)</li></ul>', '<p>This course introduces students to <strong>object-oriented programming using Java</strong>.<br>It covers fundamental programming concepts, data types, control structures, classes, and objects.<br>Students will learn to design, develop, test, and debug Java applications using modern development tools.<br>The course also introduces <strong>collections, file handling, exception handling, GUI programming, and database connectivity (JDBC)</strong> to help students build real-world software systems.</p>', '<p>After completing this course, students will be able to:</p><ol><li><strong>Understand</strong> the structure, syntax, and semantics of the Java programming language.</li><li><strong>Apply</strong> object-oriented concepts such as encapsulation, inheritance, polymorphism, and abstraction.</li><li><strong>Develop</strong> Java programs using control structures, arrays, and methods.</li><li><strong>Handle</strong> exceptions and perform file input/output operations.</li><li><strong>Use</strong> Java Collections Framework for efficient data management.</li><li><strong>Implement</strong> multithreading and synchronization in applications.</li><li><strong>Design</strong> basic GUI-based applications using Swing or JavaFX.</li><li><strong>Connect</strong> Java programs with databases using JDBC.</li><li><strong>Build and test</strong> small-scale real-world Java applications following coding best practices.</li></ol>', '0', '[\"74\"]', '[\"78\"]', '<h4><strong>Academic Prerequisites:</strong></h4><ul><li>Basic understanding of computers and operating systems</li><li>Prior experience with any programming logic (like C, Python, or pseudocode) — optional but helpful</li></ul><h4><strong>Technical Requirements:</strong></h4><ul><li>Laptop or PC (minimum 4GB RAM recommended)</li><li>Installed Java Development Kit (JDK 17 or higher)</li><li>Integrated Development Environment (IDE): IntelliJ IDEA / Eclipse / NetBeans / VS Code</li><li>Internet connection (for library access, dependencies, and tutorials)</li></ul><h4><strong>Textbooks &amp; References:</strong></h4><ol><li><i>Java: The Complete Reference</i> by <strong>Herbert Schildt</strong></li><li><i>Head First Java</i> by <strong>Kathy Sierra &amp; Bert Bates</strong></li><li><i>Effective Java</i> by <strong>Joshua Bloch</strong></li><li>Oracle Java Documentation (https://docs.oracle.com/javase)</li></ol><h3><strong>? Teaching Methodology</strong></h3><ul><li>Lectures and live coding demonstrations</li><li>Practical lab sessions</li><li>Assignments and quizzes</li><li>Midterm and final project (individual or group)</li></ul>', '0', 3, 1, 'public/uploads/main/images/03-11-2025/69088c7bd50d6.jpeg', 'public/uploads/main/images/03-11-2025/course-17621679311440427779.png', 1, 1, 1, '2025-11-03 07:05:31', '2025-11-12 06:47:15', 1),
(7, 4, 'bs physics', 'bechlor', NULL, 0, NULL, '<ul><li><strong>Educational Qualification:</strong> Intermediate or equivalent with Physics and Mathematics (Pre-Engineering / ICS / A-levels or equivalent).</li><li><strong>Minimum Marks:</strong> At least 50% marks (or as per university policy).</li><li><strong>Entry Test:</strong> Must qualify the university or board entrance/admission test.</li><li><strong>Interview:</strong> Some universities may conduct an interview for final selection.</li><li><strong>Documents Required:</strong><ul><li>Matric / O-Level certificate</li><li>Intermediate / A-Level certificate</li><li>CNIC / B-Form</li><li>Recent photographs</li><li>Domicile certificate (if require</li></ul></li></ul>', '<p>The Bachelor of Science in Physics is a four-year undergraduate program designed to provide students with a strong foundation in the principles of physics, mathematics, and scientific research. It covers key areas such as mechanics, thermodynamics, electromagnetism, quantum physics, and modern physics. The program emphasizes both theoretical understanding and practical laboratory skills, preparing students for careers in research, education, technology, and applied sciences, or for further studies in physics and related fields.</p>', '<ul><li>Demonstrate a strong understanding of fundamental concepts in classical and modern physics.</li><li>Apply mathematical and computational methods to analyze physical problems.</li><li>Design and conduct scientific experiments, and interpret data effectively.</li><li>Use modern scientific tools, equipment, and techniques for physics research and applications.</li><li>Communicate scientific ideas clearly in written and oral forms.</li><li>Work effectively both independently and as part of a multidisciplinary team.</li></ul>', '0', '[\"9\"]', '[\"68\"]', '<ul><li><strong>Educational Qualification:</strong> Intermediate or equivalent with Physics and Mathematics (Pre-Engineering / ICS / A-levels or equivalent).</li><li><strong>Minimum Marks:</strong> At least 50% marks (or as per university policy).</li><li><strong>Entry Test:</strong> Must qualify the university or board entrance/admission test.</li><li><strong>Interview:</strong> Some universities may conduct an interview for final selection.</li><li><strong>Documents Required:</strong><ul><li>Matric / O-Level certificate</li><li>Intermediate / A-Level certificate</li><li>CNIC / B-Form</li><li>Recent photographs</li><li>Domicile certificate (if require</li></ul></li></ul>', NULL, 0, 1, 'public/uploads/main/images/03-11-2025/690884b8a67dd.jpeg', 'public/uploads/main/images/03-11-2025/course-17621659441047719274.png', 1, 1, 1, '2025-11-03 06:32:24', '2025-11-03 08:21:36', 1),
(9, 6, 'Database Program', 'Database Programs', NULL, 0, NULL, '<h4><strong>Academic Prerequisites:</strong></h4><ul><li>Basic understanding of computers and operating systems</li><li>Prior experience with any programming logic (like C, Python, or pseudocode) — optional but helpful</li></ul><h4><strong>Technical Requirements:</strong></h4><ul><li>Laptop or PC (minimum 4GB RAM recommended)</li><li>Installed Java Development Kit (JDK 17 or higher)</li><li>Integrated Development Environment (IDE): IntelliJ IDEA / Eclipse / NetBeans / VS Code</li><li>Internet connection (for library access, dependencies, and tutorials)</li></ul><h4><strong>Textbooks &amp; References:</strong></h4><ol><li><i>Java: The Complete Reference</i> by <strong>Herbert Schildt</strong></li><li><i>Head First Java</i> by <strong>Kathy Sierra &amp; Bert Bates</strong></li><li><i>Effective Java</i> by <strong>Joshua Bloch</strong></li><li>Oracle Java Documentation (https://docs.oracle.com/javase)</li></ol><h3><strong>? Teaching Methodology</strong></h3><ul><li>Lectures and live coding demonstrations</li><li>Practical lab sessions</li><li>Assignments and quizzes</li><li>Midterm and final project (individual or group)</li></ul>', '<p>This course introduces students to <strong>object-oriented programming using Java</strong>.<br>It covers fundamental programming concepts, data types, control structures, classes, and objects.<br>Students will learn to design, develop, test, and debug Java applications using modern development tools.<br>The course also introduces <strong>collections, file handling, exception handling, GUI programming, and database connectivity (JDBC)</strong> to help students build real-world software systems.</p>', '<p>After completing this course, students will be able to:</p><ol><li><strong>Understand</strong> the structure, syntax, and semantics of the Java programming language.</li><li><strong>Apply</strong> object-oriented concepts such as encapsulation, inheritance, polymorphism, and abstraction.</li><li><strong>Develop</strong> Java programs using control structures, arrays, and methods.</li><li><strong>Handle</strong> exceptions and perform file input/output operations.</li><li><strong>Use</strong> Java Collections Framework for efficient data management.</li><li><strong>Implement</strong> multithreading and synchronization in applications.</li><li><strong>Design</strong> basic GUI-based applications using Swing or JavaFX.</li><li><strong>Connect</strong> Java programs with databases using JDBC.</li><li><strong>Build and test</strong> small-scale real-world Java applications following coding best practices.</li></ol>', '0', '[\"79\"]', '[\"78\",\"76\",\"79\"]', '<h4><strong>Academic Prerequisites:</strong></h4><ul><li>Basic understanding of computers and operating systems</li><li>Prior experience with any programming logic (like C, Python, or pseudocode) — optional but helpful</li></ul><h4><strong>Technical Requirements:</strong></h4><ul><li>Laptop or PC (minimum 4GB RAM recommended)</li><li>Installed Java Development Kit (JDK 17 or higher)</li><li>Integrated Development Environment (IDE): IntelliJ IDEA / Eclipse / NetBeans / VS Code</li><li>Internet connection (for library access, dependencies, and tutorials)</li></ul><h4><strong>Textbooks &amp; References:</strong></h4><ol><li><i>Java: The Complete Reference</i> by <strong>Herbert Schildt</strong></li><li><i>Head First Java</i> by <strong>Kathy Sierra &amp; Bert Bates</strong></li><li><i>Effective Java</i> by <strong>Joshua Bloch</strong></li><li>Oracle Java Documentation (https://docs.oracle.com/javase)</li></ol><h3><strong>? Teaching Methodology</strong></h3><ul><li>Lectures and live coding demonstrations</li><li>Practical lab sessions</li><li>Assignments and quizzes</li><li>Midterm and final project (individual or group)</li></ul>', '0', 4, 1, 'public/uploads/main/images/05-11-2025/690b9f196a140.jpeg', 'public/uploads/main/images/05-11-2025/course-17623693051847607631.png', 6, 0, 1, '2025-11-05 15:01:45', '2025-12-03 04:26:49', 1),
(10, 7, 'Bs Enginering', 'Bechlor', NULL, 0, NULL, '<h4><strong>Academic Prerequisites:</strong></h4><ul><li>Basic understanding of computers and operating systems</li><li>Prior experience with any programming logic (like C, Python, or pseudocode) — optional but helpful</li></ul><h4><strong>Technical Requirements:</strong></h4><ul><li>Laptop or PC (minimum 4GB RAM recommended)</li><li>Installed Java Development Kit (JDK 17 or higher)</li><li>Integrated Development Environment (IDE): IntelliJ IDEA / Eclipse / NetBeans / VS Code</li><li>Internet connection (for library access, dependencies, and tutorials)</li></ul><h4><strong>Textbooks &amp; References:</strong></h4><ol><li><i>Java: The Complete Reference</i> by <strong>Herbert Schildt</strong></li><li><i>Head First Java</i> by <strong>Kathy Sierra &amp; Bert Bates</strong></li><li><i>Effective Java</i> by <strong>Joshua Bloch</strong></li><li>Oracle Java Documentation (https://docs.oracle.com/javase)</li></ol><h3><strong>? Teaching Methodology</strong></h3><ul><li>Lectures and live coding demonstrations</li><li>Practical lab sessions</li><li>Assignments and quizzes</li><li>Midterm and final project (individual or group)</li></ul>', '<p>This course introduces students to <strong>object-oriented programming using Java</strong>.<br>It covers fundamental programming concepts, data types, control structures, classes, and objects.<br>Students will learn to design, develop, test, and debug Java applications using modern development tools.<br>The course also introduces <strong>collections, file handling, exception handling, GUI programming, and database connectivity (JDBC)</strong> to help students build real-world software systems.</p>', '<p>After completing this course, students will be able to:</p><ol><li><strong>Understand</strong> the structure, syntax, and semantics of the Java programming language.</li><li><strong>Apply</strong> object-oriented concepts such as encapsulation, inheritance, polymorphism, and abstraction.</li><li><strong>Develop</strong> Java programs using control structures, arrays, and methods.</li><li><strong>Handle</strong> exceptions and perform file input/output operations.</li><li><strong>Use</strong> Java Collections Framework for efficient data management.</li><li><strong>Implement</strong> multithreading and synchronization in applications.</li><li><strong>Design</strong> basic GUI-based applications using Swing or JavaFX.</li><li><strong>Connect</strong> Java programs with databases using JDBC.</li><li><strong>Build and test</strong> small-scale real-world Java applications following coding best practices.</li></ol>', '0', '[\"74\"]', '[\"76\"]', '<h4><strong>Academic Prerequisites:</strong></h4><ul><li>Basic understanding of computers and operating systems</li><li>Prior experience with any programming logic (like C, Python, or pseudocode) — optional but helpful</li></ul><h4><strong>Technical Requirements:</strong></h4><ul><li>Laptop or PC (minimum 4GB RAM recommended)</li><li>Installed Java Development Kit (JDK 17 or higher)</li><li>Integrated Development Environment (IDE): IntelliJ IDEA / Eclipse / NetBeans / VS Code</li><li>Internet connection (for library access, dependencies, and tutorials)</li></ul><h4><strong>Textbooks &amp; References:</strong></h4><ol><li><i>Java: The Complete Reference</i> by <strong>Herbert Schildt</strong></li><li><i>Head First Java</i> by <strong>Kathy Sierra &amp; Bert Bates</strong></li><li><i>Effective Java</i> by <strong>Joshua Bloch</strong></li><li>Oracle Java Documentation (https://docs.oracle.com/javase)</li></ol><h3><strong>? Teaching Methodology</strong></h3><ul><li>Lectures and live coding demonstrations</li><li>Practical lab sessions</li><li>Assignments and quizzes</li><li>Midterm and final project (individual or group)</li></ul>', NULL, 0, 1, 'public/uploads/main/images/12-11-2025/691466d08e97c.jpeg', 'public/uploads/main/images/12-11-2025/course-1762944720497284626.png', 2, 1, 1, '2025-11-12 06:52:00', '2025-1