(21, '2', 'War and Peace', 'War and Peace subtitle', 'War and Peace', '<p>War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace War and Peace &nbsp;&nbsp;</p>', 200.00, 10.00, 'percent', 20.00, 176.00, 16.00, 40.00, 1, 'LeoTolstoy', 'LeoTolstoy', '2024-12-10', 'public/uploads/file/02-10-2025/b935b05e295d631edccfd4e7f0681444.pdf', '1', '2025-10-02 02:41:15', '2025-11-29 04:31:59', NULL, 1),
(22, '1', 'car', 'new car', 'A sleek and durable toy car that inspires endless fun, imagination, and adventure.', '<p>This sleek and durable toy car is designed for endless fun and imagination. Made from high-quality, child-safe materials, it features smooth rolling wheels, vibrant colors, and realistic detailing that make it look just like a real car in miniature form. Perfect for kids who love speed, adventure, and creativity, this toy car encourages imaginative play while improving hand-eye coordination and motor skills. Ideal for playtime at home or on the go!</p>', 50.00, 5.00, 'percent', 10.00, 52.25, 2.25, 5.00, 0, '', '', '0000-00-00', NULL, '1', '2025-10-31 03:57:37', '2025-11-29 04:38:50', NULL, 1),
(23, '2', 'Speedy’s Big Dream', 'A little car with a big dream to race beyond imagination', 'A little car with a big dream to race beyond imagination', '<p>Speedy, a small red toy car, dreams of becoming the fastest racer in the world. From the toy shelf to the open track of imagination, Speedy’s courage and determination show that no dream is too big — even for the tiniest wheels.</p>', 100.00, 10.00, 'percent', 5.00, 104.50, 9.50, 5.00, 0, 'LeoTolstoy', 'LeoTolstoy', '2023-06-07', 'public/uploads/file/31-10-2025/97f9a6543b0472e873df1230eb4fee58.pdf', '1', '2025-10-31 04:06:55', '2025-10-31 05:08:55', NULL, 1);
