INSERT INTO `testimonials` (`id`, `body`, `author`, `profession`, `image`, `star`, `status`, `created_by`, `updated_by`, `created_at`, `updated_at`, `lms_id`) VALUES
(5, '{\"en\":\"Merkaii Xcellence Prep was a gamechanger for me. The personalized tutoring and comprehensive review courses were exactly what I needed to excel in my nursing exams\",\"es\":\"\"}', '{\"en\":\"Jamie L\",\"es\":\"\"}', '{\"en\":\"Nurse\",\"es\":\"\"}', 'public/uploads/main/images/25-07-2024/66a23d70dc0dc.png', 5, 1, 1, 1, '2024-07-25 11:56:33', '2024-07-25 11:56:33', 1),
(6, '{\"en\":\"The support and resources provided by Merkaii Xcellence Prep helped me transform my study habits and approach to learning. I couldn\\u2019t have asked for better preparation for my healthcare career\",\"es\":\"\"}', '{\"en\":\"Cornelius B\",\"es\":\"\"}', '{\"en\":\"Professional Nurse\",\"es\":\"\"}', 'public/uploads/main/images/25-07-2024/66a2416aee5e9.png', 5, 1, 1, 1, '2024-07-25 12:13:31', '2024-07-25 12:13:31', 1),
(7, '{\"en\":\"The instructors were fantastic, and the course material was very relevant. The practice questions mirrored the actual NCLEX exam. I can\'t thank this course enough for helping me succeed on my exam with 85 questions\",\"es\":\"\"}', '{\"en\":\"Aldene P\",\"es\":\"\"}', '{\"en\":\"Nurse\",\"es\":\"\"}', 'public/uploads/main/images/25-07-2024/66a241deb3ab5.png', 5, 1, 1, 1, '2024-07-25 12:15:26', '2024-07-25 12:15:26', 1),
(8, '{\"en\":\"The course content was incredibly through and easy to understand. The instructors broke down complex topics into simple concepts. Thanks to this course, I passed the NCLEX on my first try with 85 questions!\",\"es\":\"\"}', '{\"en\":\"Saran C\",\"es\":\"\"}', '{\"en\":\"Professional Nurse\",\"es\":\"\"}', 'public/uploads/main/images/25-07-2024/66a241feeff07.png', 5, 1, 1, 1, '2024-07-25 12:15:59', '2024-07-25 12:15:59', 1),
(10, '{\"en\":\"well done\",\"ar\":\"good hogya\",\"bn\":\"good hogya\",\"es\":\"good hogya\"}', '{\"en\":\"ahmed\",\"ar\":\"Afsheen\",\"bn\":\"Afsheen\",\"es\":\"Afsheen\"}', '{\"en\":\"professor\",\"ar\":\"professor\",\"bn\":\"professor\",\"es\":\"professor\"}', 'public/uploads/main/images/25-11-2025/692588a7b3dca.png', 5, 1, 1, 1, '2025-10-23 04:31:03', '2025-11-28 06:52:18', 1);
